import sys

def main():
    data = sys.stdin.read().split()
    s = data[0]
    k = int(data[1])
    vowels = set('aeiou')
    left = 0
    cnt = 0
    best = 0
    for right, ch in enumerate(s):
        if ch in vowels:
            cnt += 1
        while cnt > k:
            if s[left] in vowels:
                cnt -= 1
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    print(best)

